import numpy as np
import matplotlib.pyplot as plt
import math

# (1) Define basic functions in the desired algebra (generated by R[x]/<x^2 - ax - b>)

def square(z,a,b):
    return [z[0]**2 + b*z[1]**2, 2*z[0]*z[1] + a*z[1]**2]

def euclideanNorm(x,y):
    return math.sqrt(x*x+y*y)

def zi(c,a,b,i):
    zn = [0,0]
    for k in range(i):
        zn = f_c(zn,c,a,b)
    return(zn)

def add(z1,z2):
    return [z1[0]+z2[0],z1[1]+z2[1]]

def magn(z,a,b):
    if a*a + 4*b < 0:
        return(euclideanNorm(z[0]+0.5*z[1]*a, 0.5*z[1]*math.sqrt(-a*a - 4*b)))
    if a*a + 4*b > 0:
        return(euclideanNorm(z[0]+0.5*z[1]*a, 0.5*z[1]*math.sqrt(a*a + 4*b)))
    if a*a + 4*b == 0:
        return(euclideanNorm(z[0]+0.5*z[1]*a, 0.5*z[1]))
    
def f_c(z,c,a,b):
    return add(square(z,a,b),c)

# (2) Define the divergence tester

def Rn(c,a,b,i):
    z0 = zi(c,a,b,i)
    z1 = f_c(z0,c,a,b)
    if magn(z1,a,b) == 0:
        return -1
    else:
        return magn(z0,a,b)/magn(z1,a,b)

# (3) Create a binary array of points that do and do not diverge

def gridder(n,k,xmin,xmax,a,b):
    global grid
    grid = []
    for i in range(0,k):
        row = []
        yval = xmin + i*(xmax - xmin)/k
        for j in range(0,k):
            xval = xmin + j*(xmax - xmin)/k
            try:
                if Rn([xval,yval],a,b,n)<1.7:
                    row.append(-1)
                else:
                    row.append(1)
            except OverflowError or ZeroDivisionError:
                row.append(1)
        grid.append(row)
    return grid

# (4) Plot the binary array generated in (3)

def plotter(n,k,xmin,xmax,a,b,name):
    grid = np.array(gridder(n,k,xmin,xmax,a,b))
    plt.imshow(grid,cmap = 'gray',extent=[xmin,xmax,xmin,xmax])
    plt.savefig(name,bbox_inches='tight')
    plt.close()
    
