# plotter(30000,150,-2,2,0,1,'M(0,1) (Hyperbolic)')
# plotter(30000,150,-2,2,0,0,'M(0,0) (Dual)')

# (5) Iterate the Mandelbrot set from R[x]/<x^2 - t> from t = -1 (Complex) to t = 1 (Hyperbolic)

steps = 60
for i in range(0,steps):
    name = 'M(0,-1 + 2*' + str(i) + '%' + str(steps) + ')'
    plotter(30000,150, -2, 2, 0, -1 + 2*i/steps, name)
    print(i)
